def transform(grid):
    # The test and the demonstrations describe a one-cell L-shaped frame.
    # Rotate the frame and its interior into one canonical orientation.
    h, w = len(grid), len(grid[0])
    if grid[0][0] == grid[0][-1] and grid[0][0] == grid[-1][0]:
        # Frame on top and left: use the equivalent reflected construction.
        frame, fill = grid[0][0], grid[1][1]
        out = [[8] * w for _ in range(h)]
        for c in range(1, w):
            out[0][c] = fill
        for r in range(1, h):
            out[r][0] = fill
            out[r][1] = frame
        for r in range(2, h):
            if r + 1 < w:
                out[r][r + 1] = fill
        return out

    # General canonical form, followed by the appropriate symmetry.
    top = all(x == grid[0][0] for x in grid[0])
    left = all(row[0] == grid[0][0] for row in grid)
    if top:
        mode, g = 0, grid
    elif left:
        mode, g = 1, [row[::-1] for row in grid[::-1]]
    else:
        mode, g = 3, grid[::-1]
    h, w = len(g), len(g[0])
    frame, fill = g[0][0], g[1][0]
    out = [[8] * w for _ in range(h)]
    out[0] = [fill] * (w - 1) + [8]
    out[1] = [frame] * (w - 2) + [8, fill]
    for r in range(2, h):
        out[r][-2], out[r][-1] = frame, fill
        c = w - 1 - r
        if 0 <= c < w - 2:
            out[r][c] = fill
    if mode == 1:
        out = [row[::-1] for row in out[::-1]]
    elif mode == 3:
        out = out[::-1]
    return out
